entries[78345] = { ["name"] = "Pattern: Green Dragonscale Leggings", ["text"] = "Binds when picked up\nUse: Teaches you how to craft Green Dragonscale Leggings.\nRequires Classic Leatherworking (270)\nSell Price:\nGreen Dragonscale Leggings\nBinds when equipped\nLegs Mail\n8 Armor\n+5 [Agility or Intellect]\n+5 Stamina\n+2 Nature Resistance\nDurability 100 / 100\n\nGreen Dragon Mail (0/3)\nGreen Dragonscale Breastplate\nGreen Dragonscale Leggings\nGreen Dragonscale Gauntlets\nSell Price:\nRequires Rugged Leather (20), Green Dragonscale (25), Rune Thread\nOptional Reagents: Optional Reagent Slot (#50)" }
