entries[78842] = { ["name"] = "Mantle of Dying Light", ["text"] = "Raid Finder\nBinds when picked up\nShoulder Cloth\n3 Armor\n+1 Intellect\n+5 Stamina\n+ 2 Versatility\n+ 2 Mastery\n\nPrismatic Socket\nPrismatic Socket\nSocket Bonus: + 3 Intellect\n\nDurability 100 / 100\nClasses: Priest\nVestments of Dying Light (0/5)\nHandwraps of Dying Light\nCowl of Dying Light\nLegwraps of Dying Light\nRobes of Dying Light\nMantle of Dying Light\nLegacy Set: Bonus is inactive\n(2) Set : After using Power Word: Barrier or Divine Hymn, the mana cost of your healing spells is reduced by 25% for [ Power Infusion : 10 sec / 23 sec].\n(4) Set : Your Power Word: Shield has a 10% chance to absorb 100% additional damage, and the duration of your Holy Word abilities is increased by 33%.\nSell Price:" }
entries[78843] = { ["name"] = "Time Lord's Mantle", ["text"] = "Raid Finder\nBinds when picked up\nShoulder Cloth\n3 Armor\n+1 Intellect\n+5 Stamina\n+ 2 Critical Strike\n\nPrismatic Socket\nPrismatic Socket\nSocket Bonus: + 3 Intellect\n\nDurability 100 / 100\nClasses: Mage\nTime Lord's Regalia (0/5)\nTime Lord's Gloves\nTime Lord's Hood\nTime Lord's Leggings\nTime Lord's Robes\nTime Lord's Mantle\nLegacy Set: Bonus is inactive\n(2) Set : Your Arcane Blast has a 100% chance and your Fireball, Pyroblast, Frostfire Bolt, and Frostbolt spells have a 50% chance to grant Stolen Time, increasing your haste by 1 for 30 sec and stacking up to 10 times. When Arcane Power, Combustion, or Icy Veins expires, all stacks of Stolen Time are lost.\n(4) Set : Each stack of Stolen Time also reduces the base cooldown of Arcane Power, Combustion, and Icy Veins by 5%.\nSell Price:" }
entries[78844] = { ["name"] = "Mantle of the Faceless Shroud", ["text"] = "Raid Finder\nBinds when picked up\nShoulder Cloth\n3 Armor\n+1 Intellect\n+5 Stamina\n+ 2 Critical Strike\n\nPrismatic Socket\nPrismatic Socket\nSocket Bonus: + 3 Intellect\n\nDurability 100 / 100\nClasses: Warlock\nVestments of the Faceless Shroud (0/5)\nGloves of the Faceless Shroud\nHood of the Faceless Shroud\nLeggings of the Faceless Shroud\nRobes of the Faceless Shroud\nMantle of the Faceless Shroud\nLegacy Set: Bonus is inactive\n(2) Set : Haste increased by 5%.\n(4) Set : Increases the damage done by your Agony, Corruption, Incinerate, and Shadow Bolt spells by 5%.\nSell Price:" }
